"""Encode a fixed-transfer film of actual stored fracture/electrical observations."""
import argparse,json,hashlib,subprocess
from pathlib import Path
from PIL import Image,ImageDraw
p=argparse.ArgumentParser();p.add_argument('capture',type=Path);p.add_argument('frames',type=Path);p.add_argument('destination',type=Path);a=p.parse_args();capture=json.loads((a.capture/'capture.json').read_text());record=json.loads((a.frames/'frames.json').read_text());verify=json.loads((a.capture/'verification.json').read_text());indices=list(range(8,40));assert sorted(map(int,record['frames']))==indices;a.destination.mkdir(parents=True,exist_ok=True)
frames=[]
for ordinal,i in enumerate(indices):
 r=record['frames'][str(i)];s=capture['frames'][i];assert (r['step'],r['time'],r['source_sha256'])==(s['step'],s['time'],s['sha256']);assert hashlib.sha256((a.frames/r['image']).read_bytes()).hexdigest()==r['image_sha256'];frames.append({'video_time':ordinal/8,'simulation_time':r['time'],'step':r['step'],'source_image_sha256':r['image_sha256'],'source_observation_sha256':r['source_sha256']})
film=a.destination/'film.mp4';subprocess.run(['ffmpeg','-y','-loglevel','error','-framerate','8','-start_number','8','-i',str(a.frames/'%05d.png'),'-frames:v','32','-c:v','libx264','-preset','slow','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',str(film)],check=True)
Image.open(a.frames/'00039.png').convert('RGB').save(a.destination/'poster.webp','WEBP',quality=95,method=6)
stream=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_entries','stream=width,height,nb_read_frames,r_frame_rate,duration','-of','json',str(film)]))['streams'][0];assert stream['nb_read_frames']=='32' and stream['width']==record['size']==stream['height']
meta={'schema':'interior-animation','id':'voltage-pieces-motion-48','title':'The field gives way','description':'A fractured support opens and redirects its electrical interior. Gold potential contours tear and separate while their color records accumulated Joule dose. Thirty-two actual Julia observations, under one fixed camera and optical transfer. The contour foils are observations of voltage, not additional physical sheets.','source':{'study':'studies/voltage_between_pieces.jl','runner':'scripts/run_voltage_pieces_motion.jl','render_study':'scripts/render_voltage_pieces.py','variant_of':'voltage-pieces-48','actual_samples':32,'raw_captured_samples':40,'raw_indices':indices,'native_shape':[48,36,20],'native_nodes':34560,'native_bonds':419228,'temporal_interpolation':False,'restart_checkpoints':False,'same_approved_final_state':False,'camera':'fixed throughout: (2.8,-4,2.6), ortho2.85','potential_levels':[.12,.22,.32,.42,.52,.62,.72,.82,.9],'global_dose_optical_max':capture['global_dose_optical_max'],'physical_time_interval':[frames[0]['simulation_time'],frames[-1]['simulation_time']],'capture_verification_sha256':hashlib.sha256((a.capture/'verification.json').read_bytes()).hexdigest(),'render_record_sha256':hashlib.sha256((a.frames/'frames.json').read_bytes()).hexdigest(),'renderer_sha256':record['renderer_sha256'],'simulation_source_sha256':capture['source_sha256'],'base_sha256':capture['base_sha256'],'interpretation':'Prepared conductivity grains, quenched geometry, weak seams and grip forcing are authored. Shared 3D spring dynamics and irreversible failure change the conducting graph; newly solved voltage contours show its electrical interior. The optical foil thickness and dose palette are assignments. Fresh bounded run with32-step electrical cadence (52 in the still), same physical parameters and duration; no historical rerun or latent-heat/closed-energy claim.'},'playback':{'fps':8,'duration_seconds':4.,'width':record['size'],'height':record['size'],'rendered_width':record['size'],'rendered_height':record['size'],'samples':record['samples'],'interpolation':'none; one video frame per stored native observation'},'numerical_closure':{k:verify[k] for k in ('maximum_independent_residual','maximum_relative_power_defect','maximum_mechanical_relative_work_residual','irreversible_damage_and_nondecreasing_dose')},'frames':frames,'poster_frame_index':31,'video_sha256':hashlib.sha256(film.read_bytes()).hexdigest(),'poster_sha256':hashlib.sha256((a.destination/'poster.webp').read_bytes()).hexdigest(),'review':{'status':'pending'}}
(a.destination/'film.json').write_text(json.dumps(meta,indent=2));decoded=a.frames/'decoded';decoded.mkdir(exist_ok=True);subprocess.run(['ffmpeg','-y','-loglevel','error','-i',str(film),str(decoded/'%05d.png')],check=True);assert len(list(decoded.glob('*.png')))==32
for block in range(4):
 sheet=Image.new('RGB',(1280,684),(12,18,24));d=ImageDraw.Draw(sheet)
 for local in range(8):
  i=block*8+local;x=(local%4)*320;y=(local//4)*342;im=Image.open(decoded/f'{i+1:05d}.png').convert('RGB');im.thumbnail((320,320));sheet.paste(im,(x,y));d.text((x+8,y+322),f"{i+1}/32  t={frames[i]['simulation_time']:.3f}",fill=(235,225,204))
 sheet.save(a.frames/f'contact-{block}.jpg',quality=94)
print(json.dumps({'files':{q.name:q.stat().st_size for q in a.destination.iterdir() if q.is_file()},'decoded_frames':32,'review':'pending'},indent=2))
